  [ "$status" -eq 0 ]
  # The new 1.1.0 entry must appear before the existing 1.0.0 entry.
  new_line="$(grep -n '\[1.1.0\]' "$TMP/CHANGELOG.md" | cut -d: -f1)"
  old_line="$(grep -n '\[1.0.0\]' "$TMP/CHANGELOG.md" | cut -d: -f1)"
  [ "$new_line" -lt "$old_line" ]
}

