  grep -q '### Fixes' "$TMP/CHANGELOG.md"
  grep -q -- '- handle empty input' "$TMP/CHANGELOG.md"
  # Non-conventional noise must not appear.
  ! grep -q 'noise that should be skipped' "$TMP/CHANGELOG.md"
